excels.excel:

EXPORT WITH SHEET="利润同比对比分析表", HEADER=true,
    MAPPING={"a":"项目","b":"本期金额","c":"上期金额","d":"同比增长额","e":"同比增长率"},
    FORMAT={"b":"#,##0.00","c":"#,##0.00","d":"#,##0.00","e":"0.00%"},
    FORMULAS={
        D2:'B2-C2',E2:'D2/C2', D3:'B3-C3',E3:'D3/C3', D4:'B4-C4',E4:'D4/C4',
        D5:'B5-C5',E5:'D5/C5', D6:'B6-C6',E6:'D6/C6',
        B7:'SUM(B2:B6)',C7:'SUM(C2:C6)',D7:'B7-C7',E7:'D7/C7'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        E6:{color:red,bold:true}
    }
